import java.util.Scanner;

public class Main {
    static final int MAX_LIMIT = 510;
    static int totalN, totalM, modVal;
    static int[][] comb = new int[MAX_LIMIT][MAX_LIMIT];
    static PairType[][] dpTable = new PairType[MAX_LIMIT][MAX_LIMIT];

    static class PairType {
        int first, second;

        PairType(int first, int second) {
            this.first = first;
            this.second = second;
        }

        PairType add(PairType b) {
            return new PairType(addModulo(this.first, b.first), addModulo(this.second, b.second));
        }

        PairType multiply(PairType b) {
            long firstPart = (1L * this.first * b.first) % modVal;
            long secondPart = (1L * this.first * b.second + 1L * this.second * b.first) % modVal;
            return new PairType((int) firstPart, (int) secondPart);
        }
    }

    static int rangeSum(int start, int end) {
        return (start + end) * (end - start + 1) / 2;
    }

    static int addModulo(int a, int b) {
        int sum = a + b;
        if (sum >= modVal) sum -= modVal;
        return sum;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        totalN = sc.nextInt();
        totalM = sc.nextInt();
        modVal = sc.nextInt();

        for (int i = 0; i < MAX_LIMIT; i++) {
            comb[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                comb[i][j] = addModulo(comb[i - 1][j], comb[i - 1][j - 1]);
            }
        }

        for (int i = 0; i <= totalN; i++) {
            for (int j = 0; j <= totalM; j++) {
                dpTable[i][j] = new PairType(0, 0);
            }
        }

        for (int i = 0; i <= totalN; i++) {
            dpTable[i][0] = new PairType(1, 0);
            for (int j = 1; j <= i && j <= totalM; j++) {
                if (i != j) {
                    for (int k = 1; k <= i; k++) {
                        PairType temp = dpTable[k - 1][k - 1].multiply(dpTable[i - k][j - k + 1])
                                .multiply(new PairType(comb[j][k - 1], 0));
                        dpTable[i][j] = dpTable[i][j].add(temp);
                    }
                } else {
                    for (int k = 1; k <= i; k++) {
                        PairType t1 = dpTable[k - 1][k - 1];
                        PairType t2 = dpTable[i - k][i - k];
                        PairType combi = new PairType(comb[i - 1][k - 1], 0);
                        int factor = i + 1 - rangeSum(1, k) + rangeSum(k + 1, i) - k * (i - k);
                        PairType factor_pair = new PairType(factor, 0);
                        PairType temp = t1.multiply(t2).multiply(combi).multiply(factor_pair);
                        dpTable[i][j] = dpTable[i][j].add(temp);
                    }
                }
            }
        }
        System.out.println(dpTable[totalN][totalM].second);
        sc.close();
    }
}

